{
  "q1": {
    "stem": "What is the fundamental characteristic that distinguishes a neural network from a simple linear model?",
    "options": [
      "The use of non-linear activation functions to map the outputs of linear combinations of inputs.",
      "The ability to incorporate bias terms into the calculation of each component.",
      "The requirement that the model must be composed of multiple stacked layers.",
      "The reliance on vector notation to simplify the mathematical representation of weights."
    ],
    "explanations": [
      "Correct. The introduction of non-linear functions (like ReLU or tanh) allows the network to model complex, non-linear relationships in the data.",
      "Incorrect. Bias terms are standard components of both linear and non-linear models.",
      "Incorrect. While stacking layers is common, a single-layer network can still be a neural network if it includes a non-linearity.",
      "Incorrect. Vector notation is a tool for simplifying the math, not the defining characteristic of the network's function."
    ]
  },
  "q2": {
    "stem": "Why must the activation function used in a neural network be differentiable?",
    "options": [
      "Differentiability is necessary to allow the gradient to be calculated and propagated backward through the network during training.",
      "It ensures that the output values of the network remain bounded and do not explode to infinity.",
      "It guarantees that the model will converge to a global minimum of the cost function.",
      "It prevents the model from becoming too complex and overfitting the training data."
    ],
    "explanations": [
      "Correct. Backpropagation relies entirely on calculating derivatives (gradients) to determine how to adjust the weights.",
      "Incorrect. While some functions are bounded, differentiability is a requirement for the optimization process itself, not just for bounding the output.",
      "Incorrect. Differentiability is a prerequisite for the optimization process, but it does not guarantee convergence to a global minimum.",
      "Incorrect. Overfitting is a general problem of model complexity, not specifically solved by requiring differentiability."
    ]
  },
  "q3": {
    "statement": "The Rectified Linear Unit (ReLU) is a widely used, efficient non-linearity that speeds up convergence, but it carries the risk of gradient collapse when inputs are strongly negative.",
    "explanation_true": "Correct. The lecture notes that ReLU is super efficient and helped speed up convergence, but if the unit is strongly negative, it becomes 'dead' with no gradient.",
    "explanation_false": "Incorrect. The statement accurately summarizes the benefits and drawbacks of ReLU as discussed in the lecture."
  },
  "q4": {
    "question": "Does a neural network typically function as a single, monolithic calculation where all inputs are processed simultaneously without sequential layers?",
    "explanation_yes": "Incorrect. The lecture describes how layers are stacked on top of each other, meaning the output of one layer serves as the input to the next.",
    "explanation_no": "Correct. Neural networks are built by stacking layers, where the output of an earlier layer becomes the input for the subsequent layer."
  }
}

